//! Open Office's original 24×24 SVG icon family. The build validates the source artwork
//! in src/icons/svg/sheet and compiles paths for the native and WASM canvas renderer.

use egui::{Color32, Painter, Rect};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Icon {
    Paste,
    Cut,
    Copy,
    Brush,
    Bold,
    Italic,
    Underline,
    Strike,
    Borders,
    BorderAll,
    BorderNone,
    BorderOutside,
    BorderThick,
    Fill,
    FontColor,
    AlignTop,
    AlignMiddle,
    AlignBottom,
    AlignLeft,
    AlignCenter,
    AlignRight,
    Orientation,
    IndentDec,
    IndentInc,
    Wrap,
    Merge,
    Currency,
    Percent,
    Comma,
    DecInc,
    DecDec,
    CondFormat,
    FormatTable,
    CellStyles,
    Insert,
    Delete,
    Format,
    Sum,
    FillDown,
    Eraser,
    SortFilter,
    Find,
    Undo,
    Redo,
    Save,
    Home,
    More,
    Chevron,
    ChevronUp,
    Close,
    Check,
    Fx,
    Plus,
    Left,
    Right,
    Normal,
    PageLayout,
    PageBreak,
    Minus,
    Table,
    PivotTable,
    Chart,
    ChartBar,
    ChartLine,
    ChartPie,
    ChartScatter,
    Picture,
    Shapes,
    Link,
    Comment,
    Note,
    TextBox,
    Symbol,
    Sparkline,
    Checkbox,
    Function,
    Name,
    Trace,
    Calc,
    Filter,
    SortAsc,
    SortDesc,
    Duplicates,
    TextColumns,
    Validation,
    Group,
    Ungroup,
    Subtotal,
    Lock,
    Spell,
    Freeze,
    Zoom,
    Gridlines,
    Theme,
    Margins,
    Orient,
    SheetRtl,
    Paper,
    PrintArea,
    Script,
    Pen,
    Share,
    Search,
    Settings,
    /// Light/dark appearance: a circle, its right half filled.
    Appearance,
    Sheet,
    /// All Sheets navigator next to the sheet tabs: a list of rows with a bullet each.
    SheetList,
    Book,
    Folder,
    /// Header & Footer: a page with its top / bottom band marked.
    Header,
    Footer,
    PageNumber,
    PageCount,
    Calendar,
    Clock,
    FileName,
    /// File › Backstage navigation (line art, drawn in the navigation colour).
    Back,
    NewFile,
    OpenFolder,
    Info,
    Print,
}

/// Accent palette for icons (our own).
pub const GREEN: Color32 = Color32::from_rgb(0x10, 0x7C, 0x41);
pub const BLUE: Color32 = Color32::from_rgb(0x2B, 0x7C, 0xD3);
pub const RED: Color32 = Color32::from_rgb(0xD1, 0x3B, 0x2F);
pub const YELLOW: Color32 = Color32::from_rgb(0xF2, 0xC3, 0x2E);
pub const ORANGE: Color32 = Color32::from_rgb(0xE8, 0x7D, 0x2B);
pub const PURPLE: Color32 = Color32::from_rgb(0x88, 0x55, 0xC8);

/// Paints the shared vector artwork without relying on installed fonts.
pub fn paint(p: &Painter, rect: Rect, icon: Icon, c: Color32) {
    let name = match icon {
        Icon::Paste => "paste",
        Icon::Cut => "cut",
        Icon::Copy => "copy",
        Icon::Brush => "brush",
        Icon::Bold => "bold",
        Icon::Italic => "italic",
        Icon::Underline => "underline",
        Icon::Strike => "strike",
        Icon::Borders => "borders",
        Icon::BorderAll => "border-all",
        Icon::BorderNone => "border-none",
        Icon::BorderOutside => "border-outside",
        Icon::BorderThick => "border-thick",
        Icon::Fill => "fill",
        Icon::FontColor => "font-color",
        Icon::AlignTop => "align-top",
        Icon::AlignMiddle => "align-middle",
        Icon::AlignBottom => "align-bottom",
        Icon::AlignLeft => "align-left",
        Icon::AlignCenter => "align-center",
        Icon::AlignRight => "align-right",
        Icon::Orientation => "orientation",
        Icon::IndentDec => "indent-dec",
        Icon::IndentInc => "indent-inc",
        Icon::Wrap => "wrap",
        Icon::Merge => "merge",
        Icon::Currency => "currency",
        Icon::Percent => "percent",
        Icon::Comma => "comma",
        Icon::DecInc => "dec-inc",
        Icon::DecDec => "dec-dec",
        Icon::CondFormat => "cond-format",
        Icon::FormatTable => "format-table",
        Icon::CellStyles => "cell-styles",
        Icon::Insert => "insert",
        Icon::Delete => "delete",
        Icon::Format => "format",
        Icon::Sum => "sum",
        Icon::FillDown => "fill-down",
        Icon::Eraser => "eraser",
        Icon::SortFilter => "sort-filter",
        Icon::Find => "find",
        Icon::Undo => "undo",
        Icon::Redo => "redo",
        Icon::Save => "save",
        Icon::Home => "home",
        Icon::More => "more",
        Icon::Chevron => "chevron",
        Icon::ChevronUp => "chevron-up",
        Icon::Close => "close",
        Icon::Check => "check",
        Icon::Fx => "fx",
        Icon::Plus => "plus",
        Icon::Left => "left",
        Icon::Right => "right",
        Icon::Normal => "normal",
        Icon::PageLayout => "page-layout",
        Icon::PageBreak => "page-break",
        Icon::Minus => "minus",
        Icon::Table => "table",
        Icon::PivotTable => "pivot-table",
        Icon::Chart => "chart",
        Icon::ChartBar => "chart-bar",
        Icon::ChartLine => "chart-line",
        Icon::ChartPie => "chart-pie",
        Icon::ChartScatter => "chart-scatter",
        Icon::Picture => "picture",
        Icon::Shapes => "shapes",
        Icon::Link => "link",
        Icon::Comment => "comment",
        Icon::Note => "note",
        Icon::TextBox => "text-box",
        Icon::Symbol => "symbol",
        Icon::Sparkline => "sparkline",
        Icon::Checkbox => "checkbox",
        Icon::Function => "function",
        Icon::Name => "name",
        Icon::Trace => "trace",
        Icon::Calc => "calc",
        Icon::Filter => "filter",
        Icon::SortAsc => "sort-asc",
        Icon::SortDesc => "sort-desc",
        Icon::Duplicates => "duplicates",
        Icon::TextColumns => "text-columns",
        Icon::Validation => "validation",
        Icon::Group => "group",
        Icon::Ungroup => "ungroup",
        Icon::Subtotal => "subtotal",
        Icon::Lock => "lock",
        Icon::Spell => "spell",
        Icon::Freeze => "freeze",
        Icon::Zoom => "zoom",
        Icon::Gridlines => "gridlines",
        Icon::Theme => "theme",
        Icon::Margins => "margins",
        Icon::Orient => "orient",
        Icon::SheetRtl => "sheet-rtl",
        Icon::Paper => "paper",
        Icon::PrintArea => "print-area",
        Icon::Script => "script",
        Icon::Pen => "pen",
        Icon::Share => "share",
        Icon::Search => "search",
        Icon::Settings => "settings",
        Icon::Appearance => "appearance",
        Icon::Sheet => "sheet",
        Icon::SheetList => "sheet-list",
        Icon::Book => "book",
        Icon::Folder => "folder",
        Icon::Header => "header",
        Icon::Footer => "footer",
        Icon::PageNumber => "page-number",
        Icon::PageCount => "page-count",
        Icon::Calendar => "calendar",
        Icon::Clock => "clock",
        Icon::FileName => "file-name",
        Icon::Back => "back",
        Icon::NewFile => "new-file",
        Icon::OpenFolder => "open-folder",
        Icon::Info => "info",
        Icon::Print => "print",
    };
    let tokens = crate::theme::Tokens::get(p.ctx());
    let accent = if c == tokens.text_disabled { c } else { tokens.accent.gamma_multiply(f32::from(c.a()) / 255.0) };
    crate::office_svg::paint(p, rect, name, c, accent);
}

/// Icons offered by Insert › Icons, by name.
pub const LIBRARY: &[(&str, Icon)] = &[
    ("check", Icon::Check),
    ("close", Icon::Close),
    ("plus", Icon::Plus),
    ("minus", Icon::Minus),
    ("chart", Icon::Chart),
    ("line chart", Icon::ChartLine),
    ("pie chart", Icon::ChartPie),
    ("scatter", Icon::ChartScatter),
    ("table", Icon::Table),
    ("sum", Icon::Sum),
    ("filter", Icon::Filter),
    ("lock", Icon::Lock),
    ("comment", Icon::Comment),
    ("note", Icon::Note),
    ("picture", Icon::Picture),
    ("book", Icon::Book),
    ("folder", Icon::Folder),
    ("search", Icon::Search),
    ("calculator", Icon::Calc),
    ("link", Icon::Link),
    ("pen", Icon::Pen),
    ("share", Icon::Share),
    ("settings", Icon::Settings),
    ("home", Icon::Home),
    ("save", Icon::Save),
    ("theme", Icon::Theme),
    ("shapes", Icon::Shapes),
    ("text", Icon::TextBox),
    ("trace", Icon::Trace),
    ("validation", Icon::Validation),
];

pub fn from_name(name: &str) -> Option<Icon> {
    LIBRARY.iter().find(|(n, _)| n.eq_ignore_ascii_case(name)).map(|(_, i)| *i)
}
